import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.enableCors({ origin: process.env.FRONTEND_URL, credentials: true });
  await app.listen(3000);
}
bootstrap();

import { Module } from '@nestjs/common';
import { AuthModule } from './auth/auth.module';
import { PrismaModule } from './prisma/prisma.module';
import { OrganizationModule } from './organization/organization.module';

@Module({
  imports: [PrismaModule, AuthModule, OrganizationModule],
})
export class AppModule {}

import { Global, Module } from '@nestjs/common';
import { PrismaService } from './prisma.service';

@Global()
@Module({
  providers: [PrismaService],
  exports: [PrismaService],
})
export class PrismaModule {}

import { Injectable, OnModuleInit, OnModuleDestroy } from '@nestjs/common';
import { PrismaClient } from '@prisma/client';

@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit, OnModuleDestroy {
  async onModuleInit() {
    await this.$connect();
  }
  async onModuleDestroy() {
    await this.$disconnect();
  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import ssr from 'vite-plugin-ssr/plugin';

export default defineConfig({
  plugins: [react(), ssr()],
  server: {
    port: 5173
  }
});

import { atom } from 'nanostores';

export interface AuthState {
  token: string | null;
  user: { id: string; email: string } | null;
}

export const authStore = atom<AuthState>({
  token: null,
  user: null,
});

export function setAuth(token: string, user: { id: string; email: string }) {
  authStore.set({ token, user });
}

export function clearAuth() {
  authStore.set({ token: null, user: null });
}

import axios from 'axios';
import { authStore } from './stores/authStore';

const api = axios.create({ baseURL: import.meta.env.VITE_API_URL });

api.interceptors.request.use((config) => {
  const { token } = authStore.get();
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

export default api;

import React from 'react';
import { Button, Typography } from '@mui/material';

export default function HomePage() {
  return (
    <div className="p-8">
      <Typography variant="h4" gutterBottom>
        Welcome to the App
      </Typography>
      <Button variant="contained" color="primary" href="/login">
        Login
      </Button>
    </div>
  );
}

import React from 'react';
import { Button, Typography, TextField, Box } from '@mui/material';

export default function LoginPage() {
  return (
    <Box className="p-8 max-w-md mx-auto">
      <Typography variant="h5" gutterBottom>
        Login
      </Typography>
      <TextField label="Email" fullWidth margin="normal" />
      <TextField label="Password" type="password" fullWidth margin="normal" />
      <Button variant="contained" color="primary" fullWidth className="mt-4">
        Sign In
      </Button>
      <Box className="mt-4 flex flex-col gap-2">
        <Button variant="outlined" href="/auth/google">Sign in with Google</Button>
        <Button variant="outlined" href="/auth/github">Sign in with GitHub</Button>
      </Box>
    </Box>
  );
}

import React, { useState } from 'react';
import { Button, Typography, TextField, Box } from '@mui/material';
import api from '../src/api';

export default function OnboardingPage() {
  const [name, setName] = useState('');

  const createOrganization = async () => {
    await api.post('/organizations', { name });
    alert('Organization created');
  };

  return (
    <Box className="p-8 max-w-md mx-auto">
      <Typography variant="h5" gutterBottom>
        Create an Organization
      </Typography>
      <TextField label="Organization Name" fullWidth margin="normal" value={name} onChange={(e) => setName(e.target.value)} />
      <Button variant="contained" color="primary" fullWidth className="mt-4" onClick={createOrganization}>
        Create
      </Button>
    </Box>
  );
}
